            $shelves = json_decode($shelvesJson, true);

            $hasWhId    = Schema::hasColumn('warehouse_shelves', 'warehouse_id');
            $hasWhCode  = Schema::hasColumn('warehouse_shelves', 'warehouse_code');
            $hasWhIndex = Schema::hasColumn('warehouse_shelves', 'warehouse_index');
            $hasSlotIdx = Schema::hasColumn('warehouse_shelves', 'slot_index');
            $hasCap     = Schema::hasColumn('warehouse_shelves', 'capacity');
            $hasArch    = Schema::hasColumn('warehouse_shelves', 'archived');
            $hasSort    = Schema::hasColumn('warehouse_shelves', 'sort_order');
            $hasIsArch  = Schema::hasColumn('warehouse_shelves', 'is_archived');

            $now = now();
            foreach ($shelves as $sh) {
                $wh = $warehouseMap[$sh['wh_code']] ?? null;
                $whId = $wh ? $wh->id : null;

                $row = [
                    'name'       => $sh['name'],
                    'products'   => json_encode($sh['products']),
                    'created_at' => $now,
                    'updated_at' => $now,
                ];

                if ($hasWhId)    $row['warehouse_id']    = $whId;
                if ($hasWhCode)  $row['warehouse_code']  = $sh['wh_code'];
                if ($hasWhIndex) $row['warehouse_index'] = $sh['wh_index'];
                if ($hasSlotIdx) $row['slot_index']      = $sh['slot_index'];
                if ($hasCap)     $row['capacity']        = $sh['capacity'];
                if ($hasArch)    $row['archived']        = 0;
